import assert from 'node:assert/strict';
import {test} from 'node:test';
import {readFileSync} from 'node:fs';
import {DatabaseSync} from 'node:sqlite';
import ts from 'typescript';
import * as errors from '../lib/rogue-api-errors.mjs';
import * as storage from '../lib/game-storage.mjs';
import * as origin from '../lib/request-origin.mjs';
import * as game from '../lib/rogue-classic-game.mjs';
import {createFixture} from './browser/ui-readability/fixture.mjs';

// Execute the actual TypeScript route with local SQLite and injected platform
// bindings. No live credentials, production saves or network calls are used.
function compile(path){return ts.transpileModule(readFileSync(new URL(path,import.meta.url),'utf8'),{compilerOptions:{module:ts.ModuleKind.CommonJS,target:ts.ScriptTarget.ES2022}}).outputText;}
const routeSource=compile('../app/api/rogue-classic/route.ts'),rankingSource=compile('../lib/rogue-ranking.ts');
function harness(options={}){
 const sqlite=new DatabaseSync(':memory:'),logs=[];let beforeWrite=options.beforeWrite;
 sqlite.exec('CREATE TABLE saves(user_id TEXT PRIMARY KEY,data TEXT,updated_at INTEGER,revision INTEGER); CREATE TABLE admin_audit(id INTEGER PRIMARY KEY,action TEXT,detail TEXT)');
 if(options.exists!==false)sqlite.prepare('INSERT INTO saves VALUES(?,?,0,0)').run('private-account',JSON.stringify(options.document||{counter:0,adventure:{untouched:true}}));
 const db={prepare(sql){let args=[];return {bind(...values){args=values;return this;},async first(){if(options.readError)throw options.readError;return sqlite.prepare(sql).get(...args);},async run(){
  if(sql.startsWith('UPDATE saves')){if(beforeWrite){const callback=beforeWrite;beforeWrite=null;callback(sqlite);}if(options.writeError)throw options.writeError;}
  const result=sqlite.prepare(sql).run(...args);return {meta:{changes:Number(result.changes)}};
 }};},async batch(statements){sqlite.exec('BEGIN');try{const result=[];for(const statement of statements)result.push(await statement.run());sqlite.exec('COMMIT');return result;}catch(error){sqlite.exec('ROLLBACK');throw error;}}};
 const ranking={};new Function('require','exports',rankingSource)(()=>({env:{DB:db}}),ranking);
 const modules={
  'cloudflare:workers':{env:{DB:db}},'@/app/chatgpt-auth':{getChatGPTUser:async()=>{if(options.authError)throw options.authError;return options.unauthenticated?null:{userId:'private-account'};}},
  '@/lib/request-origin.mjs':origin,'@/lib/game-storage.mjs':{...storage,...options.storage},
  '@/lib/rogue-classic-game.mjs':{applyClassicAction:options.apply||((doc)=>{doc.counter++;return {};}),classicGameView:options.view||((doc)=>({counter:doc.counter}))},
  '@/lib/rogue-pickup-config':{getRoguePickup:async()=>{if(options.pickupError)throw options.pickupError;return {sourceId:null,version:0};}},'@/lib/rogue-ranking':ranking,'@/lib/rogue-api-errors.mjs':errors,
 },route={};
 new Function('require','exports','console',routeSource)(name=>{assert.ok(modules[name],name);return modules[name];},route,{error:(...args)=>{try{logs.push(JSON.parse(args[0]));}catch{logs.push({raw:args});}}});
 return {sqlite,logs,get:(query='')=>route.GET(new Request('http://localhost/api/rogue-classic'+query)),row:()=>sqlite.prepare('SELECT data,revision FROM saves').get(),post:(body={action:'turn',revision:0})=>route.POST(new Request('http://localhost/api/rogue-classic',{method:'POST',headers:{origin:'http://localhost','content-type':'application/json'},body:typeof body==='string'?body:JSON.stringify(body)}))};
}
async function failure(h,body,status,code){const response=await h.post(body),data=await response.json();assert.equal(response.status,status);assert.equal(data.code,code);assert.match(data.requestId,/^[0-9a-f-]{36}$/);assert.equal(response.headers.get('x-request-id'),data.requestId);assert.equal(h.logs.at(-1).requestId,data.requestId);return data;}

test('POST rejects malformed bodies before reading or writing saves',async()=>{
 for(const body of ['{',null,[],{action:'turn'},{action:'turn',revision:-1},{action:'turn',revision:0.5}]){const h=harness();await failure(h,body,400,'INVALID_REQUEST');assert.equal(h.row().revision,0);assert.equal(h.logs[0].stage,'parse');h.sqlite.close();}
});
test('POST distinguishes stale revision and CAS conflict without applying twice',async()=>{
 const h=harness();await failure(h,{action:'turn',revision:3},409,'REVISION_CONFLICT');assert.equal(h.row().revision,0);
 const responses=await Promise.all([h.post(),h.post()]);assert.deepEqual(responses.map(r=>r.status).sort(),[200,409]);
 const conflict=await responses.find(r=>r.status===409).json();assert.equal(conflict.code,'REVISION_CONFLICT');assert.equal(h.row().revision,1);assert.equal(JSON.parse(h.row().data).counter,1);assert.equal(h.logs.at(-1).saveOutcome,'rejected');h.sqlite.close();
});
test('POST keeps ambiguous game Error separate from confirmed save conflicts and internal runtime exceptions',async()=>{
 for(const [error,status,code] of [[Error('먼저 이벤트 선택을 마치세요.'),409,'ACTION_FAILED'],[new TypeError('private-account token=secret'),500,'INTERNAL_ERROR']]){
  const h=harness({apply(doc){doc.counter++;throw error;}}),before=h.row().data;
  const data=await failure(h,{action:'turn',command:{type:'move',move:'private-name'},revision:0},status,code);
  assert.equal(h.row().data,before);assert.equal(h.logs[0].stage,'action');assert.equal(h.logs[0].commandType,'move');
  const serialized=JSON.stringify(h.logs);for(const value of ['private-account','secret','private-name','이벤트'])assert.ok(!serialized.includes(value));
  if(status===500)assert.ok(!data.error.includes('secret'));h.sqlite.close();
 }
});
test('POST read, encode and write failures return 500 instead of a false 409',async()=>{
 for(const [stage,options] of [['read',{readError:Error('private database detail')}],['encode',{storage:{encodeGameData:async()=>{throw Error('private codec detail');}}}],['write',{writeError:Error('private database detail')}]]){
  const h=harness(options),before=h.row();await failure(h,undefined,500,'INTERNAL_ERROR');assert.deepEqual(h.row(),before);assert.equal(h.logs[0].stage,stage);assert.equal(h.logs[0].saveOutcome,stage==='write'?'unknown':'not_attempted');assert.ok(!JSON.stringify(h.logs).includes('private'));h.sqlite.close();
 }
});
test('POST constructs and serializes response before any persistent save mutation',async()=>{
 for(const view of [()=>{throw Error('DTO failed');},()=>({bad:1n})])for(const exists of [true,false]){
  const h=harness({view,exists}),before=h.row();await failure(h,undefined,500,'INTERNAL_ERROR');assert.deepEqual(h.row(),before);assert.equal(h.logs[0].stage,'view');assert.equal(h.logs[0].saveOutcome,'not_attempted');h.sqlite.close();
 }
});
test('pickup CAS failure cannot consume eggs or claim a revision-only conflict',async()=>{
 const h=harness({beforeWrite(db){db.prepare('INSERT INTO admin_audit VALUES(1,?,?)').run('setRoguePickup','{}');}}),before=h.row();
 await failure(h,{action:'drawEggs',revision:0},409,'SAVE_OR_PICKUP_CONFLICT');assert.deepEqual(h.row(),before);h.sqlite.close();
});
test('ranking SQL guard follows actual save CAS success in the SQLite batch',async()=>{
 for(const conflict of [false,true]){
  const h=harness({document:{classic:{slots:[{coinRewards:[5]}]}},apply(){return {};},beforeWrite:conflict?db=>db.prepare('UPDATE saves SET revision=1').run():undefined});
  const response=await h.post();assert.equal(response.status,conflict?409:200);
  const ranking=h.sqlite.prepare('SELECT best_wave FROM rogue_rankings').get();assert.equal(ranking?.best_wave,conflict?undefined:5);h.sqlite.close();
 }
});
test('actual battle action survives API encode/view/commit and retains unrelated progress',async()=>{
 const document=createFixture('battle'),h=harness({document,apply:game.applyClassicAction,view:game.classicGameView});
 const before=JSON.parse(h.row().data),response=await h.post({action:'turn',command:{type:'move',move:'disable'},revision:0});
 assert.equal(response.status,200);const result=await response.json(),after=await storage.decodeGameData(h.row().data);
 assert.equal(result.revision,1);assert.equal(h.row().revision,1);assert.deepEqual(after.adventure,before.adventure);assert.deepEqual(after.classic.slots[1],before.classic.slots[1]);assert.equal(after.coins,before.coins);assert.equal(h.logs.length,0);h.sqlite.close();
});
test('unknown request fields and error metadata never enter diagnostics',async()=>{
 const h=harness({apply(){throw {name:'private-name',message:'secret'};}});
 await failure(h,{action:'sensitiveAccountName',command:{type:'secret',token:'secret'},revision:0},500,'INTERNAL_ERROR');
 assert.equal(h.logs[0].action,'other');assert.equal(h.logs[0].errorType,'unknown');assert.ok(!JSON.stringify(h.logs).includes('secret'));h.sqlite.close();
});

test('GET auth, pickup, decode/read and view failures never disclose raw errors or stacks',async()=>{
 const marker='synthetic-private-account-token-marker';
 for(const [stage,options] of [['auth',{authError:Error(marker)}],['pickup',{pickupError:Error(marker)}],['read',{readError:Error(marker)}],['read',{storage:{decodeGameData:async()=>{throw new SyntaxError(marker);}}}],['view',{view(){throw Error(marker);}}],['view',{view:()=>({bad:1n})}]]){
  const h=harness(options),before=h.row(),response=await h.get(),data=await response.json();
  assert.equal(response.status,500);assert.equal(data.code,'INTERNAL_ERROR');assert.match(data.requestId,/^[0-9a-f-]{36}$/);assert.equal(response.headers.get('x-request-id'),data.requestId);assert.equal(response.headers.get('cache-control'),'private, no-store');
  assert.equal(h.logs.length,1);assert.equal(h.logs[0].event,'classic_get_failure');assert.equal(h.logs[0].stage,stage);assert.equal(h.logs[0].requestId,data.requestId);assert.equal(h.logs[0].saveOutcome,'not_attempted');
  const output=JSON.stringify({data,logs:h.logs});for(const value of [marker,'private-account','stack','raw'])assert.ok(!output.includes(value));assert.deepEqual(h.row(),before);h.sqlite.close();
 }
});
test('GET retains successful game, pickup-only and unauthenticated contracts without writes',async()=>{
 const h=harness({document:createFixture('battle'),view:game.classicGameView}),before=h.row();
 const response=await h.get(),data=await response.json();assert.equal(response.status,200);assert.equal(data.revision,0);assert.ok(data.battle);assert.equal(data.starters,undefined);assert.equal(h.logs.length,0);assert.deepEqual(h.row(),before);
 assert.deepEqual(await (await h.get('?pickupOnly=1')).json(),{pickupVersion:0});assert.deepEqual(h.row(),before);h.sqlite.close();
 const loggedOut=harness({unauthenticated:true});assert.equal((await loggedOut.get()).status,401);assert.equal(loggedOut.logs.length,0);loggedOut.sqlite.close();
});
test('two otherwise valid battle actions at one revision produce one commit and a classified conflict',async()=>{
 const h=harness({document:createFixture('battle'),apply:game.applyClassicAction,view:game.classicGameView});
 const command={action:'turn',command:{type:'move',move:'disable'},revision:0};
 const responses=await Promise.all([h.post(command),h.post(command)]);assert.deepEqual(responses.map(r=>r.status).sort(),[200,409]);
 const success=await responses.find(r=>r.status===200).json(),conflict=await responses.find(r=>r.status===409).json();assert.equal(conflict.code,'REVISION_CONFLICT');assert.equal(success.revision,1);assert.equal(h.logs[0].stage,'write');assert.equal(h.logs[0].saveOutcome,'rejected');
 const saved=await storage.decodeGameData(h.row().data);assert.equal(saved.classic.slots[0].party[0].pp.disable,19);const restored=await(await h.get()).json();assert.equal(restored.revision,1);
 assert.equal((await h.post({...command,revision:restored.revision})).status,200);assert.equal(h.row().revision,2);h.sqlite.close();
});
test('a real move during pending trainer dialogue is ACTION_FAILED, not a save conflict',async()=>{
 const h=harness({document:createFixture('trainer'),apply:game.applyClassicAction,view:game.classicGameView}),before=h.row();
 const rejected=await failure(h,{action:'turn',command:{type:'move',move:'disable'},revision:0},409,'ACTION_FAILED');assert.match(rejected.error,/대화/);assert.equal(h.logs[0].stage,'action');assert.equal(h.logs[0].saveOutcome,'not_attempted');assert.deepEqual(h.row(),before);
 let current=await(await h.get()).json();while(current.run.npcDialogueQueue?.length){const dialogue=current.run.npcDialogueQueue[0],response=await h.post({action:'npcDialogueSkip',revision:current.revision,dialogueId:dialogue.id,index:dialogue.index});assert.equal(response.status,200);current=await response.json();}
 assert.equal((await h.post({action:'turn',command:{type:'move',move:'disable'},revision:current.revision})).status,200);h.sqlite.close();
});

test('legacy Dream alias repair is read-only on GET and persists atomically on the next valid POST',async()=>{const doc=createFixture('rewards'),run=doc.classic.slots[doc.classic.activeSlot],other={id:'other',safe:true};doc.classic.slots[1]=other;run.screen='reward';run.encounter={kind:'mystery',key:'weird-dream'};run.mystery={type:'weird-dream',stage:'resolved',job:'transform'};run.combat=null;delete run.dreamMoveIdentityRule;run.party[0].moves=['Tackle','몸통박치기','Growl'];run.party[0].pp={tackle:3,growl:5};run.party[0].roguePPUps={tackle:2};const h=harness({document:doc,apply:game.applyClassicAction,view:game.classicGameView}),before=h.row().data,get=await h.get(),shown=await get.json();assert.equal(get.status,200);assert.deepEqual(shown.run.party[0].moves,['Tackle','Growl']);assert.equal(shown.run.dreamMoveAliasBackups,undefined);assert.equal(h.row().data,before);const failed=await h.post({action:'not-a-valid-action',revision:0});assert.equal(failed.status,409);assert.equal(h.row().data,before);const response=await h.post({action:'cancelSelection',revision:0});assert.equal(response.status,200);const row=h.row(),saved=await storage.decodeGameData(row.data);assert.equal(row.revision,1);assert.deepEqual(saved.classic.slots[0].party[0].moves,['Tackle','Growl']);assert.deepEqual(saved.classic.slots[0].party[0].pp,{tackle:3,growl:5});assert.equal(saved.classic.slots[0].party[0].roguePPUps.tackle,2);assert.deepEqual(saved.classic.slots[0].dreamMoveAliasBackups[0].moves,['Tackle','몸통박치기','Growl']);assert.deepEqual(saved.classic.slots[1],other);assert.deepEqual(saved.adventure,doc.adventure);h.sqlite.close();});
test('legacy Dream alias repair does not overwrite a competing revision',async()=>{const doc=createFixture('rewards'),run=doc.classic.slots[doc.classic.activeSlot];run.screen='reward';run.encounter={kind:'mystery',key:'weird-dream'};run.mystery={type:'weird-dream',stage:'resolved',job:'transform'};run.combat=null;delete run.dreamMoveIdentityRule;run.party[0].moves=['Tackle','몸통박치기'];const h=harness({document:doc,apply:game.applyClassicAction,view:game.classicGameView,beforeWrite(sqlite){const competing=structuredClone(doc);competing.adventure.concurrentMarker='preserved';sqlite.prepare('UPDATE saves SET data=?, revision=revision+1 WHERE user_id=?').run(JSON.stringify(competing),'private-account');}}),response=await h.post({action:'cancelSelection',revision:0});assert.equal(response.status,409);const body=await response.json();assert.equal(body.code,'REVISION_CONFLICT');const saved=await storage.decodeGameData(h.row().data);assert.equal(h.row().revision,1);assert.equal(saved.adventure.concurrentMarker,'preserved');assert.deepEqual(saved.classic.slots[0].party[0].moves,['Tackle','몸통박치기']);assert.equal(saved.classic.slots[0].dreamMoveAliasBackups,undefined);h.sqlite.close();});
test('progressed alias repair requires confirmation and saves only the selected party member',async()=>{const doc=createFixture('rewards'),run=doc.classic.slots[doc.classic.activeSlot];run.screen='reward';run.encounter={kind:'wild'};run.mystery=null;run.combat=null;run.party[0].moves=['Tackle','몸통박치기','Growl'];run.party[0].pp={tackle:3,growl:5};const boxId=run.party[0].boxId,other=structuredClone(run.party.slice(1)),h=harness({document:doc,apply:game.applyClassicAction,view:game.classicGameView}),before=h.row().data;const read=await h.get(),view=await read.json();assert.equal(read.status,200);assert.deepEqual(view.run.party[0].moveAliasRepair.pairs,[{keep:'Tackle',remove:'몸통박치기'}]);assert.equal(h.row().data,before);const denied=await h.post({action:'repairMoveAliases',boxId,expectedMoves:run.party[0].moves,revision:0});assert.equal(denied.status,409);assert.equal(h.row().data,before);const savedResponse=await h.post({action:'repairMoveAliases',boxId,expectedMoves:run.party[0].moves,confirm:true,revision:0});assert.equal(savedResponse.status,200);const saved=await storage.decodeGameData(h.row().data),after=saved.classic.slots[0];assert.deepEqual(after.party[0].moves,['Tackle','Growl']);assert.deepEqual(after.party[0].pp,{tackle:3,growl:5});assert.deepEqual(after.party.slice(1),other);assert.deepEqual(after.dreamMoveAliasBackups[0].moves,['Tackle','몸통박치기','Growl']);h.sqlite.close();});
