async function activeTrainerTestAliasApiFixture({sketch=false,challenge=false}={}){const {makeReferenceMon}=await import('../lib/rogue-reference.mjs'),doc=await activeAliasApiFixture(),run=doc.classic.slots[0];run.wave=122;run.biome=4;run.screen='mystery';run.mysteryRule='part-timer-v18';run.party=[makeReferenceMon(challenge?1:151,100,{boxId:'lead',moves:challenge?['Tackle']:['Psystrike','Aura Sphere']}),sketch?makeReferenceMon(235,100,{boxId:'alias',moves:['Tackle','Sketch','몸통박치기'],rogueSketchRule:'source-v1',rogueSketchPP:[2,1,17]}):makeReferenceMon(1,100,{boxId:'alias',moves:['Tackle','몸통박치기','Growl'],pp:{tackle:3,growl:5},roguePPUps:{tackle:2}})];run.encounter={kind:'mystery',key:'a-trainers-test'};run.mystery={type:'a-trainers-test',stage:'choose',trainerId:121};run.combat=null;run.npcDialogueQueue=[];if(challenge){run.challenges=sketch?[{id:12,value:2},{id:10,value:2}]:[{id:0,value:1},{id:1,value:12},{id:5,value:1},{id:8,value:3}];run.challengeEligibilityRule='source-subset-v1';}game.applyClassicAction(doc,{action:'mysterySelect',job:'battle'});game.applyClassicAction(doc,{action:'mysteryConfirm'});while(run.npcDialogueQueue?.length){const d=run.npcDialogueQueue[0];game.applyClassicAction(doc,{action:'npcDialogueSkip',dialogueId:d.id,index:d.index});}return doc;}
test('trainer test event reserve review commits without advancing event or turn',async()=>{for(const sketch of [false,true]){const doc=await activeTrainerTestAliasApiFixture({sketch}),h=harness({document:doc,apply:game.applyClassicAction,view:game.classicGameView}),before=h.row().data,view=await(await h.get()).json(),preview=view.run.party.find(p=>p.boxId==='alias').moveAliasRepair;assert.ok(preview);assert.equal(h.row().data,before);const response=await h.post({action:'repairMoveAliases',boxId:'alias',confirm:true,expectedMoves:preview.moves,revision:0,...(sketch?{expectedSketchPP:preview.sketchPP,removeIndex:2}:{})});assert.equal(response.status,200);const result=await response.json();assert.deepEqual(result.battle.requests,view.battle.requests);assert.equal(result.battle.turn,view.battle.turn);const saved=await storage.decodeGameData(h.row().data),run=saved.classic.slots[0];assert.deepEqual(run.mystery,doc.classic.slots[0].mystery);assert.deepEqual(saved.classic.slots[1],{id:'other',safe:true});if(sketch)assert.deepEqual(run.party.find(p=>p.boxId==='alias').rogueSketchPP,[2,1]);else assert.deepEqual(run.party.find(p=>p.boxId==='alias').moves,['Tackle','Growl']);h.sqlite.close();}});
