async function activeWeirdDreamAliasApiFixture({sketch=false}={}){const {makeReferenceMon}=await import('../lib/rogue-reference.mjs'),doc=await activeAliasApiFixture(),run=doc.classic.slots[0];run.wave=82;run.biome=1;run.screen='mystery';run.party=[makeReferenceMon(151,50,{boxId:'lead',moves:['Psystrike']}),sketch?makeReferenceMon(235,50,{boxId:'alias',moves:['Tackle','Sketch','몸통박치기'],rogueSketchRule:'source-v1',rogueSketchPP:[2,1,17]}):makeReferenceMon(1,50,{boxId:'alias',moves:['Tackle','몸통박치기','Growl'],pp:{tackle:3,growl:5},roguePPUps:{tackle:2}}),makeReferenceMon(25,50,{boxId:'ally',moves:['Thunderbolt']})];const drafts=run.party.map((mon,i)=>{const next=makeReferenceMon([10,13,16][i],50,{boxId:'dream'+i,moves:['Splash']});return {oldBoxId:mon.boxId,mon:next,dexIvs:next.ivs,eggMoveIndex:null};});run.formItems={};run.encounter={kind:'mystery',key:'weird-dream'};run.mystery={type:'weird-dream',stage:'choose',drafts,alternateTrainer:{name:'또 다른 나',title:'트레이너',moneyMultiplier:0}};run.combat=null;run.npcDialogueQueue=[];game.applyClassicAction(doc,{action:'mysterySelect',job:'battle'});game.applyClassicAction(doc,{action:'mysteryConfirm'});const active=doc.classic.slots[0];while(active.npcDialogueQueue?.length){const d=active.npcDialogueQueue[0];game.applyClassicAction(doc,{action:'npcDialogueSkip',dialogueId:d.id,index:d.index});}return doc;}
