import {wildEventReviewFixture} from './fixtures/wild-event-alias.mjs';
test('wild event reserve review commits without advancing combat or event',async()=>{
 for(const type of ['mysterious-chest','berries','fight-or-flight','uncommon-breed'])for(const sketch of [false,true]){
  const doc=wildEventReviewFixture(type,{sketch,reserveId:'alias'}),h=harness({document:doc,apply:game.applyClassicAction,view:game.classicGameView}),before=h.row().data,view=await(await h.get()).json(),preview=view.run.party.find(p=>p.boxId==='alias').moveAliasRepair;
  assert.ok(preview,type);assert.equal(h.row().data,before);
  const response=await h.post({action:'repairMoveAliases',boxId:'alias',confirm:true,expectedMoves:preview.moves,revision:0,...(sketch?{expectedSketchPP:preview.sketchPP,removeIndex:2}:{})});assert.equal(response.status,200,type);
  const result=await response.json(),saved=await storage.decodeGameData(h.row().data),run=saved.classic.slots[0];assert.deepEqual(result.battle.requests,view.battle.requests);assert.equal(result.battle.turn,view.battle.turn);assert.deepEqual(run.mystery,doc.classic.slots[0].mystery);assert.deepEqual(saved.classic.slots[1],doc.classic.slots[1]);assert.deepEqual(saved.adventure,doc.adventure);
  if(sketch)assert.deepEqual(run.party.find(p=>p.boxId==='alias').rogueSketchPP,[2,1]);else assert.deepEqual(run.party.find(p=>p.boxId==='alias').moves,['Tackle','Growl']);h.sqlite.close();
 }
});
