test('dark deal reserve review preserves sacrificed party and event on API',async()=>{for(const sketch of [false,true]){const doc=wildEventReviewFixture('dark-deal',{sketch,reserveId:'alias'}),h=harness({document:doc,apply:game.applyClassicAction,view:game.classicGameView}),before=h.row().data,view=await(await h.get()).json(),preview=view.run.party.find(p=>p.boxId==='alias').moveAliasRepair;assert.ok(preview);assert.equal(h.row().data,before);const response=await h.post({action:'repairMoveAliases',boxId:'alias',confirm:true,expectedMoves:preview.moves,revision:0,...(sketch?{expectedSketchPP:preview.sketchPP,removeIndex:2}:{})});assert.equal(response.status,200);const result=await response.json(),saved=await storage.decodeGameData(h.row().data);assert.equal(result.battle.turn,view.battle.turn);assert.deepEqual(result.battle.requests,view.battle.requests);assert.deepEqual(saved.classic.slots[0].mystery,doc.classic.slots[0].mystery);assert.equal(saved.classic.slots[0].party.some(p=>p.boxId==='lead'),false);assert.deepEqual(saved.classic.slots[1],doc.classic.slots[1]);assert.deepEqual(saved.adventure,doc.adventure);h.sqlite.close();}});
